info += '🆔 书号：' + (dd.book_id || '') + '\n';
info += '📕 书名：' + (dd.book_name || '') + '\n';
info += '🎯 状况：' + (dd.creation_status == '0' ? '连载中' : '已完结') + '\n';
info += '✏️ 开坑：' + String(dd.create_time || '').substring(0, 10) + '\n';
info += '🕰️ 更新：' + (dd.last_publish_time ? fmtTime(dd.last_publish_time) : '') + '\n';
info += '⌨️ 字数：' + (dd.word_number || '0') + '字\n';
info += '🏷️ 标签：' + (dd.tags || '') + '\n';
